using System;using System.Linq;using System.Threading;using System.Threading.Tasks;using System.Windows;using System.Windows.Controls;using System.Windows.Markup;
namespace FoolLauncher {
 public sealed class VanillaPage {
  readonly Window Window;readonly VanillaService Service;readonly Func<bool> Busy;readonly Func<Func<IProgress<Update>,CancellationToken,Task>,Task> Runner;readonly Action<Instance> Added;readonly Action<string> Navigate;readonly Border Page;readonly ListBox List=new ListBox();readonly TextBox Search=new TextBox();readonly ComboBox Types=new ComboBox();readonly TextBlock Title=new TextBlock(),Latest=new TextBlock(),Status=new TextBlock(),Selection=new TextBlock();readonly Button Refresh=new Button(),Install=new Button(),Stop=new Button();VanillaManifest Manifest;bool Loading,Working;CancellationTokenSource Cancel;
  public VanillaPage(Window window,PackService service,Func<bool> busy,Func<Func<IProgress<Update>,CancellationToken,Task>,Task> runner,Action<Instance> added,Action<string> navigate){Window=window;Service=new VanillaService(service);Busy=busy??(()=>false);Runner=runner??(job=>job(new Progress<Update>(),CancellationToken.None));Added=added??(i=>{});Navigate=navigate;Page=(Border)window.FindName("VanillaPage");var grid=new Grid();grid.RowDefinitions.Add(new RowDefinition{Height=GridLength.Auto});grid.RowDefinitions.Add(new RowDefinition{Height=new GridLength(1,GridUnitType.Star)});grid.RowDefinitions.Add(new RowDefinition{Height=GridLength.Auto});var top=new StackPanel();Title.FontSize=27;Title.FontWeight=FontWeights.SemiBold;top.Children.Add(Title);Latest.FontSize=12;Latest.Margin=new Thickness(0,8,0,14);Latest.SetResourceReference(TextBlock.ForegroundProperty,"Brush.Muted");Latest.TextWrapping=TextWrapping.Wrap;top.Children.Add(Latest);var filters=new DockPanel{Margin=new Thickness(0,0,0,14)};Refresh.Padding=new Thickness(15,9,15,9);Refresh.Margin=new Thickness(12,0,0,0);DockPanel.SetDock(Refresh,Dock.Right);filters.Children.Add(Refresh);Types.Width=175;Types.Foreground=System.Windows.Media.Brushes.Black;Types.Margin=new Thickness(12,0,0,0);DockPanel.SetDock(Types,Dock.Right);filters.Children.Add(Types);Search.Padding=new Thickness(10,8,10,8);Search.SetResourceReference(Control.BackgroundProperty,"Brush.Log");Search.SetResourceReference(Control.ForegroundProperty,"Brush.Text");filters.Children.Add(Search);top.Children.Add(filters);grid.Children.Add(top);List.Background=System.Windows.Media.Brushes.Transparent;List.BorderThickness=new Thickness(0);ScrollViewer.SetHorizontalScrollBarVisibility(List,ScrollBarVisibility.Disabled);List.ItemTemplate=(DataTemplate)XamlReader.Parse("<DataTemplate xmlns='http://schemas.microsoft.com/winfx/2006/xaml/presentation'><Grid><Grid.ColumnDefinitions><ColumnDefinition/><ColumnDefinition Width='Auto'/></Grid.ColumnDefinitions><TextBlock Text='{Binding Title}' FontSize='15' FontWeight='SemiBold'/><TextBlock Grid.Column='1' Text='{Binding Date}' Foreground='{DynamicResource Brush.Muted}' FontSize='12' Margin='12,0,0,0' VerticalAlignment='Center'/></Grid></DataTemplate>");Grid.SetRow(List,1);grid.Children.Add(List);var footer=new StackPanel{Margin=new Thickness(0,14,0,0)};Selection.TextWrapping=TextWrapping.Wrap;Selection.Margin=new Thickness(0,0,0,10);footer.Children.Add(Selection);var actions=new WrapPanel();Install.Padding=new Thickness(20,11,20,11);Install.SetResourceReference(Control.BackgroundProperty,"Brush.Accent");Install.SetResourceReference(Control.ForegroundProperty,"Brush.AccentText");Install.IsEnabled=false;actions.Children.Add(Install);Stop.Padding=new Thickness(14,11,14,11);Stop.Visibility=Visibility.Collapsed;actions.Children.Add(Stop);footer.Children.Add(actions);Status.TextWrapping=TextWrapping.Wrap;Status.FontSize=12;Status.SetResourceReference(TextBlock.ForegroundProperty,"Brush.Muted");Status.Margin=new Thickness(0,10,0,0);footer.Children.Add(Status);Grid.SetRow(footer,2);grid.Children.Add(footer);Page.Child=grid;
   Search.TextChanged+=(s,e)=>Filter();Types.SelectionChanged+=(s,e)=>{if(!Loading)Filter();};List.SelectionChanged+=(s,e)=>Selected();Refresh.Click+=async(s,e)=>await Load();Stop.Click+=(s,e)=>{if(Cancel!=null)Cancel.Cancel();};Install.Click+=async(s,e)=>{var version=List.SelectedItem as VanillaVersion;if(version==null||Busy()||Working)return;LoaderSelection loader;if(!LoaderSelectionDialog.Show(Window,version.id,out loader))return;await Job(async(p,ct)=>{var instance=await Service.Install(version,loader,p,Added,ct);Status.Text=UiText.T("安装完成，已加入游戏库。");Navigate("library");});};Window.Closed+=(s,e)=>{if(Cancel!=null)Cancel.Cancel();};RefreshLanguage();}
  void Selected(){var v=List.SelectedItem as VanillaVersion;Selection.Text=v==null?UiText.T("选择版本后下载安装。早期版本可能需要在 Java 管理中下载 Java 8。"):v.Title+"  ·  "+v.Date;Install.IsEnabled=v!=null&&!Working&&!Busy();}
  void Filter(){if(Manifest==null)return;string type=Types.SelectedIndex==1?"release":Types.SelectedIndex==2?"snapshot":Types.SelectedIndex==3?"old_beta":Types.SelectedIndex==4?"old_alpha":"";string text=Search.Text.Trim();var prior=List.SelectedItem as VanillaVersion;List.ItemsSource=Manifest.versions.Where(v=>(type==""||v.type==type)&&(text==""||v.id.IndexOf(text,StringComparison.OrdinalIgnoreCase)>=0)).ToArray();if(prior!=null)List.SelectedItem=List.Items.Cast<VanillaVersion>().FirstOrDefault(v=>v.id==prior.id);Selected();}
  public void RefreshLanguage(){Title.Text=UiText.T("原版 Minecraft 下载");Refresh.Content=UiText.T("刷新版本");Install.Content=UiText.T("下载并安装到游戏库");Stop.Content=UiText.T("停止任务");Search.ToolTip=UiText.T("搜索版本号，例如 1.20.1、24w、b1.7.3");Loading=true;int selected=Types.SelectedIndex;Types.Items.Clear();foreach(string type in new[]{"全部版本","正式版","快照 / 预发布版","远古 Beta","远古 Alpha"})Types.Items.Add(UiText.T(type));Types.SelectedIndex=Math.Max(0,selected);Loading=false;if(Manifest!=null){string release="",snapshot="";if(Manifest.latest!=null){Manifest.latest.TryGetValue("release",out release);Manifest.latest.TryGetValue("snapshot",out snapshot);}Latest.Text=UiText.T("官方收录版本：")+Manifest.versions.Length+UiText.T("  ·  最新正式版：")+release+UiText.T("  ·  最新快照：")+snapshot;}else Latest.Text=UiText.T("加载 Mojang 官方完整版本清单，包含正式版、快照和早期历史版本。");Filter();Selected();}
  async Task Job(Func<IProgress<Update>,CancellationToken,Task> work){if(Busy()||Working)return;await Runner(async(p,ct)=>{Working=true;Cancel=CancellationTokenSource.CreateLinkedTokenSource(ct);Refresh.IsEnabled=false;Install.IsEnabled=false;Stop.Visibility=Visibility.Visible;var progress=new Progress<Update>(u=>{if(Working)Status.Text=u.Message;p.Report(u);});try{await work(progress,Cancel.Token);}catch(OperationCanceledException){Status.Text=UiText.T("任务已停止，已下载文件保留，可从游戏库继续校验补全。");}catch(Exception ex){Status.Text=ex.Message;throw;}finally{Working=false;Cancel.Dispose();Cancel=null;Refresh.IsEnabled=true;Stop.Visibility=Visibility.Collapsed;Selected();}});Selected();}
  async Task Load(){await Job(async(p,ct)=>{Status.Text=UiText.T("正在读取官方版本清单…");Manifest=await Service.List(ct);RefreshLanguage();Status.Text=Service.Cached?UiText.T("网络暂不可用，当前显示已缓存的官方清单。"):UiText.T("清单已刷新；请选择版本。下载安装不会自动启动游戏。");});}
  public void Show(bool visible){Page.Visibility=visible?Visibility.Visible:Visibility.Collapsed;if(visible&&Manifest==null&&Window.IsLoaded&&!Working&&!Busy()){var ignored=Load();}}
